-- C06: tasks, recipient inbox, durable reminders and push. No financial postings.
CREATE TABLE crm.tasks(company_id uuid NOT NULL REFERENCES core.companies(id),id uuid NOT NULL,creator_id uuid NOT NULL REFERENCES identity.users(id),assignee_id uuid NOT NULL REFERENCES identity.users(id),customer_id uuid,branch_id uuid,title text NOT NULL CHECK(length(btrim(title))BETWEEN 1 AND 200),description text NOT NULL DEFAULT ''CHECK(length(description)<=10000),priority text NOT NULL CHECK(priority IN('LOW','NORMAL','HIGH','URGENT')),state text NOT NULL DEFAULT 'OPEN'CHECK(state IN('OPEN','IN_PROGRESS','COMPLETED','CANCELLED','DELETED')),due_at timestamptz,reminder_at timestamptz,reminder_generation bigint NOT NULL DEFAULT 1,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,id),FOREIGN KEY(company_id,customer_id)REFERENCES crm.customers(company_id,id),FOREIGN KEY(company_id,branch_id)REFERENCES crm.customer_branches(company_id,id),CHECK(branch_id IS NULL OR customer_id IS NOT NULL),CHECK(reminder_at IS NULL OR due_at IS NOT NULL AND reminder_at<=due_at));
CREATE INDEX ON crm.tasks(company_id,assignee_id,state,due_at,id);
CREATE INDEX ON crm.tasks(reminder_at)WHERE reminder_at IS NOT NULL AND state IN('OPEN','IN_PROGRESS');
CREATE TABLE crm.task_history(company_id uuid NOT NULL,task_id uuid NOT NULL,version bigint NOT NULL,snapshot jsonb NOT NULL,actor_id uuid NOT NULL REFERENCES identity.users(id),action text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,task_id,version),FOREIGN KEY(company_id,task_id)REFERENCES crm.tasks(company_id,id));
CREATE TABLE crm.task_changes(company_id uuid NOT NULL,sequence bigint NOT NULL,task_id uuid NOT NULL,snapshot jsonb NOT NULL,PRIMARY KEY(company_id,sequence),FOREIGN KEY(company_id,task_id)REFERENCES crm.tasks(company_id,id));
CREATE TABLE crm.notification_messages(company_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),recipient_id uuid NOT NULL REFERENCES identity.users(id),source_type text NOT NULL CHECK(source_type IN('TASK','NOTE')),source_id uuid NOT NULL,source_version bigint NOT NULL,event text NOT NULL CHECK(event IN('ASSIGNED','UPDATED','COMPLETED','CANCELLED','REOPENED','REMINDER','NOTE_UPDATED')),generation bigint NOT NULL DEFAULT 0,read_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '90 days',PRIMARY KEY(company_id,id),UNIQUE(company_id,recipient_id,source_type,source_id,source_version,event,generation));
CREATE INDEX ON crm.notification_messages(company_id,recipient_id,created_at,id);
CREATE TABLE crm.notification_changes(company_id uuid NOT NULL,sequence bigint NOT NULL,message_id uuid NOT NULL,PRIMARY KEY(company_id,sequence),FOREIGN KEY(company_id,message_id)REFERENCES crm.notification_messages(company_id,id));
CREATE TABLE crm.reminder_deliveries(company_id uuid NOT NULL,task_id uuid NOT NULL,generation bigint NOT NULL,state text NOT NULL CHECK(state IN('DELIVERED','SKIPPED')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,task_id,generation),FOREIGN KEY(company_id,task_id)REFERENCES crm.tasks(company_id,id));
CREATE TABLE crm.note_follows(company_id uuid NOT NULL,note_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES identity.users(id),enabled boolean NOT NULL,version bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,note_id,actor_id),FOREIGN KEY(company_id,note_id)REFERENCES crm.collaboration_objects(company_id,id));
CREATE TABLE crm.notification_preferences(company_id uuid NOT NULL REFERENCES core.companies(id),actor_id uuid NOT NULL REFERENCES identity.users(id),push_enabled boolean NOT NULL DEFAULT true,tasks_push boolean NOT NULL DEFAULT true,notes_push boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,actor_id));
-- Tokens are secrets: neither app nor portal has direct SELECT on these two tables.
CREATE TABLE crm.push_subscriptions(company_id uuid NOT NULL,device_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES identity.users(id),token text NOT NULL CHECK(length(token)BETWEEN 20 AND 4096),token_hash bytea NOT NULL CHECK(token_hash=sha256(convert_to(token,'UTF8'))),platform text NOT NULL CHECK(platform IN('ANDROID','IOS','WEB')),enabled boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,device_id),UNIQUE(company_id,token_hash),FOREIGN KEY(company_id,device_id)REFERENCES crm.mobile_devices(company_id,id));
CREATE TABLE crm.push_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL,message_id uuid NOT NULL,device_id uuid NOT NULL,subscription_version bigint NOT NULL,state text NOT NULL DEFAULT 'PENDING'CHECK(state IN('PENDING','PROCESSING','RETRY','SUCCEEDED','FAILED','CANCELLED','UNKNOWN')),attempts int NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5),lease_token uuid,lease_until timestamptz,available_at timestamptz NOT NULL DEFAULT now(),last_error text,provider_id text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,message_id,device_id,subscription_version),FOREIGN KEY(company_id,message_id)REFERENCES crm.notification_messages(company_id,id),FOREIGN KEY(company_id,device_id)REFERENCES crm.push_subscriptions(company_id,device_id));
CREATE INDEX ON crm.push_jobs(state,available_at);
CREATE TABLE crm.push_attempts(job_id uuid NOT NULL REFERENCES crm.push_jobs(id),company_id uuid NOT NULL REFERENCES core.companies(id),attempt int NOT NULL,state text NOT NULL,error text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(job_id,attempt));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['tasks','task_history','task_changes','notification_messages','notification_changes','reminder_deliveries','note_follows','notification_preferences','push_subscriptions','push_jobs','push_attempts']LOOP EXECUTE format('ALTER TABLE crm.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE crm.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY company_scope ON crm.%I USING(company_id=core.current_company())WITH CHECK(company_id=core.current_company())',t);IF t IN('task_history','task_changes','notification_changes','reminder_deliveries','push_attempts')THEN EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON crm.%I FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation()',t);END IF;IF t IN('tasks','notification_messages','note_follows','notification_preferences','push_subscriptions')THEN EXECUTE format('CREATE TRIGGER touch_version BEFORE UPDATE ON crm.%I FOR EACH ROW EXECUTE FUNCTION core.touch_version()',t);END IF;END LOOP;END$$;
INSERT INTO identity.permissions(code,description)VALUES('crm.tasks.read','Read own or office managed tasks'),('crm.tasks.write','Create and progress authorized tasks'),('crm.tasks.manage','Office task administration'),('crm.notifications.read','Read own notification inbox'),('crm.push.write','Maintain own push subscriptions and preferences');
CREATE FUNCTION identity.seed_task_roles(c uuid)RETURNS void LANGUAGE sql SET search_path=pg_catalog AS $$INSERT INTO identity.role_permissions(company_id,role_id,permission_code)SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND((r.code IN('ADMIN','OFFICE','SALES','FINANCE','WAREHOUSE','PROCUREMENT','PRICING_MANAGER')AND p.code IN('crm.tasks.read','crm.tasks.write','crm.notifications.read','crm.push.write','crm.mobile.sync'))OR(r.code IN('ADMIN','OFFICE')AND p.code='crm.tasks.manage'))ON CONFLICT DO NOTHING$$;
DO $$DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_task_roles(c);END LOOP;PERFORM set_config('htt.company_id','',true);END$$;
CREATE FUNCTION crm.member_permission(p_user uuid,p_cap text)RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT EXISTS(SELECT 1 FROM identity.memberships m JOIN identity.users u ON u.id=m.user_id AND u.active JOIN identity.membership_roles mr ON mr.company_id=m.company_id AND mr.membership_id=m.id JOIN identity.role_permissions rp ON rp.company_id=mr.company_id AND rp.role_id=mr.role_id WHERE m.company_id=core.current_company()AND m.user_id=p_user AND m.active AND rp.permission_code=p_cap)$$;
CREATE FUNCTION crm.member_customer(p_user uuid,p_customer uuid)RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT p_customer IS NULL OR(crm.member_permission(p_user,'customers.read')AND EXISTS(SELECT 1 FROM crm.customers WHERE company_id=core.current_company()AND id=p_customer)AND(crm.member_permission(p_user,'customers.all')OR EXISTS(SELECT 1 FROM identity.customer_assignments a JOIN identity.memberships m ON m.company_id=a.company_id AND m.id=a.membership_id WHERE a.company_id=core.current_company()AND a.customer_id=p_customer AND m.user_id=p_user AND m.active)))$$;
CREATE FUNCTION crm.task_visible_to(p_id uuid,p_user uuid)RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT crm.member_permission(p_user,'crm.tasks.read')AND EXISTS(SELECT 1 FROM crm.tasks t WHERE t.company_id=core.current_company()AND t.id=p_id AND(t.creator_id=p_user OR t.assignee_id=p_user OR crm.member_permission(p_user,'crm.tasks.manage'))AND crm.member_customer(p_user,t.customer_id))$$;
CREATE FUNCTION crm.require_task(p_id uuid,p_write boolean DEFAULT false)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN IF NOT EXISTS(SELECT 1 FROM crm.tasks WHERE company_id=core.current_company()AND id=p_id)THEN RAISE EXCEPTION 'Task unavailable' USING ERRCODE='HT404';END IF;IF NOT crm.task_visible_to(p_id,core.current_actor())THEN RAISE EXCEPTION 'Task access denied' USING ERRCODE='42501';END IF;IF p_write THEN PERFORM crm.require_mobile('crm.tasks.write');END IF;END$$;
CREATE FUNCTION crm.task_json(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_task(p_id);RETURN(SELECT jsonb_build_object('id',id,'creatorId',creator_id,'assigneeId',assignee_id,'customerId',customer_id,'branchId',branch_id,'title',CASE WHEN state='DELETED'THEN NULL ELSE title END,'description',CASE WHEN state='DELETED'THEN NULL ELSE description END,'priority',priority,'state',state,'dueAt',due_at,'reminderAt',reminder_at,'version',version,'createdAt',created_at,'updatedAt',updated_at)FROM crm.tasks WHERE company_id=core.current_company()AND id=p_id);END$$;
CREATE FUNCTION crm.notification_source_visible(p_type text,p_id uuid,p_user uuid)RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT CASE WHEN p_type='TASK'THEN crm.task_visible_to(p_id,p_user)AND EXISTS(SELECT 1 FROM crm.tasks WHERE company_id=core.current_company()AND id=p_id AND state<>'DELETED')WHEN p_type='NOTE'THEN crm.member_permission(p_user,'crm.collaboration.read')AND EXISTS(SELECT 1 FROM crm.collaboration_objects o WHERE o.company_id=core.current_company()AND o.id=p_id AND o.kind='NOTE'AND o.state='ACTIVE'AND crm.member_customer(p_user,o.customer_id)AND(o.visibility='TEAM'OR o.owner_id=p_user OR o.visibility='OFFICE'AND crm.member_permission(p_user,'crm.collaboration.manage')))ELSE false END$$;
CREATE FUNCTION crm.message_visible(p_id uuid)RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$SELECT crm.mobile_permission('crm.notifications.read')AND EXISTS(SELECT 1 FROM crm.notification_messages m WHERE m.company_id=core.current_company()AND m.id=p_id AND m.recipient_id=core.current_actor()AND m.expires_at>now()AND crm.notification_source_visible(m.source_type,m.source_id,m.recipient_id))$$;
CREATE FUNCTION crm.message_json(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN IF NOT crm.message_visible(p_id)THEN RAISE EXCEPTION 'Message unavailable' USING ERRCODE='HT404';END IF;RETURN(SELECT jsonb_build_object('id',id,'sourceType',source_type,'sourceId',source_id,'sourceVersion',source_version,'event',event,'readAt',read_at,'version',version,'createdAt',created_at,'expiresAt',expires_at)FROM crm.notification_messages WHERE company_id=core.current_company()AND id=p_id);END$$;
CREATE FUNCTION crm.emit_message(p_id uuid)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE n bigint;BEGIN UPDATE crm.mobile_heads SET sequence=sequence+1 WHERE company_id=core.current_company()RETURNING sequence INTO n;INSERT INTO crm.notification_changes(company_id,sequence,message_id)VALUES(core.current_company(),n,p_id);END$$;
CREATE FUNCTION crm.queue_message(p_user uuid,p_type text,p_id uuid,p_version bigint,p_event text,p_generation bigint DEFAULT 0)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE m uuid;BEGIN IF NOT crm.member_permission(p_user,'crm.notifications.read')OR NOT crm.notification_source_visible(p_type,p_id,p_user)THEN RETURN;END IF;
 INSERT INTO crm.notification_messages(company_id,recipient_id,source_type,source_id,source_version,event,generation)VALUES(core.current_company(),p_user,p_type,p_id,p_version,p_event,p_generation)ON CONFLICT DO NOTHING RETURNING id INTO m;IF m IS NULL THEN RETURN;END IF;PERFORM crm.emit_message(m);
 INSERT INTO crm.push_jobs(company_id,message_id,device_id,subscription_version)SELECT s.company_id,m,s.device_id,s.version FROM crm.push_subscriptions s JOIN crm.mobile_devices d ON d.company_id=s.company_id AND d.id=s.device_id AND d.active LEFT JOIN crm.notification_preferences p ON p.company_id=s.company_id AND p.actor_id=s.actor_id WHERE s.company_id=core.current_company()AND s.actor_id=p_user AND s.enabled AND crm.member_permission(p_user,'crm.push.write')AND coalesce(p.push_enabled,true)AND CASE WHEN p_type='TASK'THEN coalesce(p.tasks_push,true)ELSE coalesce(p.notes_push,true)END ON CONFLICT DO NOTHING;
END$$;
CREATE FUNCTION crm.emit_task(p_id uuid,p_action text)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE t crm.tasks;j jsonb;n bigint;u uuid;ev text;BEGIN SELECT*INTO t FROM crm.tasks WHERE company_id=core.current_company()AND id=p_id;j:=crm.task_json(p_id);INSERT INTO crm.task_history(company_id,task_id,version,snapshot,actor_id,action)VALUES(t.company_id,t.id,t.version,j,core.current_actor(),p_action);UPDATE crm.mobile_heads SET sequence=sequence+1 WHERE company_id=t.company_id RETURNING sequence INTO n;INSERT INTO crm.task_changes(company_id,sequence,task_id,snapshot)VALUES(t.company_id,n,t.id,j);
 IF t.state='DELETED'THEN RETURN;END IF;ev:=CASE p_action WHEN'CREATE'THEN'ASSIGNED'WHEN'COMPLETE'THEN'COMPLETED'WHEN'CANCEL'THEN'CANCELLED'WHEN'REOPEN'THEN'REOPENED'ELSE'UPDATED'END;FOR u IN SELECT DISTINCT x FROM unnest(ARRAY[t.assignee_id,t.creator_id])x WHERE x<>core.current_actor()LOOP PERFORM crm.queue_message(u,'TASK',t.id,t.version,ev);END LOOP;END$$;
CREATE FUNCTION crm.validate_task(p_data jsonb)RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN IF jsonb_typeof(p_data)IS DISTINCT FROM'object'OR pg_column_size(p_data)>20000 OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_data)k WHERE k NOT IN('title','description','assigneeId','customerId','branchId','priority','dueAt','reminderAt'))OR coalesce(length(btrim(p_data->>'title')),0)NOT BETWEEN 1 AND 200 OR coalesce(length(p_data->>'description'),0)>10000 OR coalesce(p_data->>'priority','')NOT IN('LOW','NORMAL','HIGH','URGENT')OR(p_data->>'assigneeId')IS NULL OR(p_data->>'reminderAt')IS NOT NULL AND((p_data->>'dueAt')IS NULL OR(p_data->>'reminderAt')::timestamptz>(p_data->>'dueAt')::timestamptz)THEN RAISE EXCEPTION 'Invalid task payload' USING ERRCODE='HR422';END IF;END$$;
CREATE FUNCTION crm.task_command(p_id uuid,p_action text,p_version bigint,p_data jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();t crm.tasks;assignee uuid;customer uuid;branch uuid;due timestamptz;remind timestamptz;manager boolean;BEGIN
 PERFORM crm.require_mobile('crm.tasks.write');PERFORM crm.require_mobile('crm.tasks.read');IF p_action<>'CREATE'THEN PERFORM crm.require_task(p_id,true);END IF;PERFORM crm.lock_mobile_head();PERFORM crm.require_mobile('crm.tasks.write');PERFORM crm.require_mobile('crm.tasks.read');
 IF p_action IN('CREATE','UPDATE')THEN PERFORM crm.validate_task(p_data);assignee:=(p_data->>'assigneeId')::uuid;customer:=(p_data->>'customerId')::uuid;branch:=(p_data->>'branchId')::uuid;due:=(p_data->>'dueAt')::timestamptz;remind:=(p_data->>'reminderAt')::timestamptz;
 IF NOT crm.member_customer(core.current_actor(),customer)OR NOT crm.member_customer(assignee,customer)OR NOT crm.member_permission(assignee,'crm.tasks.read')OR NOT crm.member_permission(assignee,'crm.tasks.write')THEN RAISE EXCEPTION 'Task or assignee access denied' USING ERRCODE='42501';END IF;
 IF branch IS NOT NULL AND NOT EXISTS(SELECT 1 FROM crm.customer_branches WHERE company_id=c AND id=branch AND customer_id=customer AND active)THEN RAISE EXCEPTION 'Active branch belonging to customer required' USING ERRCODE='HR422';END IF;END IF;
 IF p_action IS NULL THEN RAISE EXCEPTION 'Task action required' USING ERRCODE='HR422';END IF;
 IF p_action='CREATE'THEN
 IF p_id IS NULL OR p_id='00000000-0000-0000-0000-000000000000'THEN RAISE EXCEPTION 'Stable task ID required' USING ERRCODE='HR422';END IF;IF EXISTS(SELECT 1 FROM crm.tasks WHERE company_id=c AND id=p_id)THEN RAISE EXCEPTION 'Task ID exists' USING ERRCODE='HR409';END IF;
 INSERT INTO crm.tasks(company_id,id,creator_id,assignee_id,customer_id,branch_id,title,description,priority,due_at,reminder_at)VALUES(c,p_id,core.current_actor(),assignee,customer,branch,btrim(p_data->>'title'),coalesce(p_data->>'description',''),p_data->>'priority',due,remind);
 ELSE
 PERFORM crm.require_task(p_id,true);SELECT*INTO t FROM crm.tasks WHERE company_id=c AND id=p_id FOR UPDATE;IF t.version IS DISTINCT FROM p_version OR t.state='DELETED'THEN RAISE EXCEPTION 'Task version/state conflict' USING ERRCODE='HR409';END IF;manager:=t.creator_id=core.current_actor()OR crm.mobile_permission('crm.tasks.manage');
 IF p_action='UPDATE'THEN IF NOT manager THEN RAISE EXCEPTION 'Only creator or office may edit task details or reassign' USING ERRCODE='42501';END IF;IF t.state NOT IN('OPEN','IN_PROGRESS')THEN RAISE EXCEPTION 'Reopen task before editing' USING ERRCODE='HR409';END IF;IF t.customer_id IS DISTINCT FROM customer OR t.branch_id IS DISTINCT FROM branch THEN RAISE EXCEPTION 'Task customer and branch are immutable' USING ERRCODE='HR422';END IF;
 IF t.assignee_id<>assignee THEN UPDATE crm.mobile_heads SET acl_version=acl_version+1 WHERE company_id=c;END IF;
 UPDATE crm.tasks SET title=btrim(p_data->>'title'),description=coalesce(p_data->>'description',''),assignee_id=assignee,priority=p_data->>'priority',due_at=due,reminder_at=remind,reminder_generation=reminder_generation+CASE WHEN assignee_id IS DISTINCT FROM assignee OR due_at IS DISTINCT FROM due OR reminder_at IS DISTINCT FROM remind THEN 1 ELSE 0 END WHERE company_id=c AND id=p_id;
 ELSIF p_action='START'AND t.state='OPEN'THEN UPDATE crm.tasks SET state='IN_PROGRESS'WHERE company_id=c AND id=p_id;
 ELSIF p_action='COMPLETE'AND t.state IN('OPEN','IN_PROGRESS')THEN UPDATE crm.tasks SET state='COMPLETED'WHERE company_id=c AND id=p_id;
 ELSIF p_action='CANCEL'AND manager AND t.state IN('OPEN','IN_PROGRESS')THEN UPDATE crm.tasks SET state='CANCELLED'WHERE company_id=c AND id=p_id;
 ELSIF p_action='REOPEN'AND manager AND t.state IN('COMPLETED','CANCELLED')THEN UPDATE crm.tasks SET state='OPEN',reminder_generation=reminder_generation+1 WHERE company_id=c AND id=p_id;
 ELSIF p_action='DELETE'AND manager THEN UPDATE crm.tasks SET state='DELETED',title='Deleted task',description=''WHERE company_id=c AND id=p_id;UPDATE crm.mobile_heads SET acl_version=acl_version+1 WHERE company_id=c;
 ELSIF NOT manager AND p_action IN('CANCEL','REOPEN','DELETE')THEN RAISE EXCEPTION 'Only creator or office may administer task' USING ERRCODE='42501';
 ELSE RAISE EXCEPTION 'Invalid task transition' USING ERRCODE='HR409';END IF;
 END IF;PERFORM crm.emit_task(p_id,p_action);RETURN crm.task_json(p_id);
END$$;
CREATE FUNCTION crm.task_list(p_filter jsonb)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE result jsonb;BEGIN PERFORM crm.require_mobile('crm.tasks.read');IF(p_filter->>'size')::int NOT BETWEEN 1 AND 100 OR(p_filter->>'offset')::int<0 THEN RAISE EXCEPTION 'Invalid page' USING ERRCODE='HR422';END IF;SELECT coalesce(jsonb_agg(body),'[]')INTO result FROM(SELECT crm.task_json(t.id)body FROM crm.tasks t WHERE t.company_id=core.current_company()AND t.state<>'DELETED'AND crm.task_visible_to(t.id,core.current_actor())AND((p_filter->>'assigneeId')IS NULL OR t.assignee_id=(p_filter->>'assigneeId')::uuid)AND((p_filter->>'customerId')IS NULL OR t.customer_id=(p_filter->>'customerId')::uuid)AND((p_filter->>'state')IS NULL OR t.state=p_filter->>'state')AND((p_filter->>'dueBefore')IS NULL OR t.due_at<(p_filter->>'dueBefore')::timestamptz)ORDER BY t.due_at NULLS LAST,t.created_at,t.id LIMIT(p_filter->>'size')::int OFFSET(p_filter->>'offset')::int)s;RETURN result;END$$;
CREATE FUNCTION crm.task_history_view(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_task(p_id);IF EXISTS(SELECT 1 FROM crm.tasks WHERE company_id=core.current_company()AND id=p_id AND state='DELETED')THEN RAISE EXCEPTION 'Task unavailable' USING ERRCODE='HT404';END IF;RETURN(SELECT coalesce(jsonb_agg(jsonb_build_object('snapshot',snapshot,'actorId',actor_id,'action',action,'createdAt',created_at)ORDER BY version),'[]')FROM crm.task_history WHERE company_id=core.current_company()AND task_id=p_id AND((snapshot->>'creatorId')::uuid=core.current_actor()OR(snapshot->>'assigneeId')::uuid=core.current_actor()OR crm.mobile_permission('crm.tasks.manage')));END$$;
CREATE FUNCTION crm.message_list(p_unread boolean,p_size int,p_offset int)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile('crm.notifications.read');IF p_size NOT BETWEEN 1 AND 100 OR p_offset<0 THEN RAISE EXCEPTION 'Invalid page' USING ERRCODE='HR422';END IF;RETURN(SELECT jsonb_build_object('unreadCount',(SELECT count(*)FROM crm.notification_messages WHERE company_id=core.current_company()AND read_at IS NULL AND crm.message_visible(id)),'items',(SELECT coalesce(jsonb_agg(body),'[]')FROM(SELECT crm.message_json(id)body FROM crm.notification_messages WHERE company_id=core.current_company()AND(NOT p_unread OR read_at IS NULL)AND crm.message_visible(id)ORDER BY created_at DESC,id LIMIT p_size OFFSET p_offset)s)));END$$;
CREATE FUNCTION crm.mark_message(p_id uuid,p_version bigint,p_read boolean)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN IF NOT crm.message_visible(p_id)THEN RAISE EXCEPTION 'Message unavailable' USING ERRCODE='HT404';END IF;PERFORM crm.lock_mobile_head();IF NOT crm.message_visible(p_id)THEN RAISE EXCEPTION 'Message access changed' USING ERRCODE='HT404';END IF;PERFORM 1 FROM crm.notification_messages WHERE company_id=core.current_company()AND id=p_id AND version=p_version FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Message version conflict' USING ERRCODE='HR409';END IF;UPDATE crm.notification_messages SET read_at=CASE WHEN p_read THEN coalesce(read_at,now())ELSE NULL END WHERE company_id=core.current_company()AND id=p_id;PERFORM crm.emit_message(p_id);RETURN crm.message_json(p_id);END$$;
CREATE FUNCTION crm.follow_note(p_id uuid,p_enabled boolean,p_version bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE v bigint;BEGIN PERFORM crm.require_mobile('crm.notifications.read');PERFORM crm.require_collab(p_id);PERFORM crm.lock_mobile_head();PERFORM crm.require_collab(p_id);IF NOT EXISTS(SELECT 1 FROM crm.collaboration_objects WHERE company_id=core.current_company()AND id=p_id AND kind='NOTE'AND state='ACTIVE')THEN RAISE EXCEPTION 'Active note required' USING ERRCODE='HT404';END IF;SELECT version INTO v FROM crm.note_follows WHERE company_id=core.current_company()AND note_id=p_id AND actor_id=core.current_actor()FOR UPDATE;IF coalesce(v,0)IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'Follow version conflict' USING ERRCODE='HR409';END IF;INSERT INTO crm.note_follows(company_id,note_id,actor_id,enabled)VALUES(core.current_company(),p_id,core.current_actor(),p_enabled)ON CONFLICT(company_id,note_id,actor_id)DO UPDATE SET enabled=excluded.enabled RETURNING version INTO v;RETURN jsonb_build_object('noteId',p_id,'enabled',p_enabled,'version',v);END$$;
CREATE FUNCTION crm.note_notification()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE u uuid;BEGIN IF NEW.kind='NOTE'AND NEW.state='ACTIVE'THEN FOR u IN SELECT actor_id FROM crm.note_follows WHERE company_id=NEW.company_id AND note_id=NEW.id AND enabled AND actor_id<>core.current_actor()LOOP PERFORM crm.queue_message(u,'NOTE',NEW.id,NEW.version,'NOTE_UPDATED');END LOOP;END IF;RETURN NEW;END$$;
CREATE TRIGGER note_notification AFTER UPDATE ON crm.collaboration_objects FOR EACH ROW EXECUTE FUNCTION crm.note_notification();
CREATE FUNCTION crm.deliver_due_reminders(p_limit int DEFAULT 50)RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE candidate record;t crm.tasks;n int:=0;ok boolean;BEGIN IF p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid reminder batch' USING ERRCODE='HR422';END IF;
 FOR candidate IN SELECT x.company_id,x.id FROM crm.tasks x WHERE x.state IN('OPEN','IN_PROGRESS')AND x.reminder_at<=now()AND NOT EXISTS(SELECT 1 FROM crm.reminder_deliveries r WHERE r.company_id=x.company_id AND r.task_id=x.id AND r.generation=x.reminder_generation)ORDER BY x.company_id,x.reminder_at,x.id LIMIT p_limit LOOP
 PERFORM set_config('htt.company_id',candidate.company_id::text,true);PERFORM crm.lock_mobile_head();SELECT*INTO t FROM crm.tasks WHERE company_id=candidate.company_id AND id=candidate.id FOR UPDATE;
 IF t.state NOT IN('OPEN','IN_PROGRESS')OR t.reminder_at IS NULL OR t.reminder_at>now()OR EXISTS(SELECT 1 FROM crm.reminder_deliveries WHERE company_id=t.company_id AND task_id=t.id AND generation=t.reminder_generation)THEN CONTINUE;END IF;
 ok:=crm.member_permission(t.assignee_id,'crm.notifications.read')AND crm.notification_source_visible('TASK',t.id,t.assignee_id);IF ok THEN PERFORM crm.queue_message(t.assignee_id,'TASK',t.id,t.version,'REMINDER',t.reminder_generation);END IF;INSERT INTO crm.reminder_deliveries(company_id,task_id,generation,state)VALUES(t.company_id,t.id,t.reminder_generation,CASE WHEN ok THEN'DELIVERED'ELSE'SKIPPED'END);n:=n+1;
 END LOOP;PERFORM set_config('htt.company_id','',true);RETURN n;END$$;
CREATE FUNCTION crm.preferences_view()RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile('crm.push.write');RETURN coalesce((SELECT jsonb_build_object('pushEnabled',push_enabled,'tasksPush',tasks_push,'notesPush',notes_push,'version',version)FROM crm.notification_preferences WHERE company_id=core.current_company()AND actor_id=core.current_actor()),jsonb_build_object('pushEnabled',true,'tasksPush',true,'notesPush',true,'version',0));END$$;
CREATE FUNCTION crm.set_preferences(p_version bigint,p_push boolean,p_tasks boolean,p_notes boolean)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE v bigint;BEGIN PERFORM crm.require_mobile('crm.push.write');PERFORM crm.lock_mobile_head();PERFORM crm.require_mobile('crm.push.write');SELECT version INTO v FROM crm.notification_preferences WHERE company_id=core.current_company()AND actor_id=core.current_actor()FOR UPDATE;IF coalesce(v,0)IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'Preference version conflict' USING ERRCODE='HR409';END IF;INSERT INTO crm.notification_preferences(company_id,actor_id,push_enabled,tasks_push,notes_push)VALUES(core.current_company(),core.current_actor(),p_push,p_tasks,p_notes)ON CONFLICT(company_id,actor_id)DO UPDATE SET push_enabled=excluded.push_enabled,tasks_push=excluded.tasks_push,notes_push=excluded.notes_push;RETURN crm.preferences_view();END$$;
CREATE FUNCTION crm.subscription_view(p_device uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile('crm.push.write');PERFORM crm.require_mobile_device(p_device);RETURN coalesce((SELECT jsonb_build_object('deviceId',device_id,'platform',platform,'enabled',enabled,'version',version)FROM crm.push_subscriptions WHERE company_id=core.current_company()AND device_id=p_device AND actor_id=core.current_actor()),jsonb_build_object('deviceId',p_device,'enabled',false,'version',0));END$$;
CREATE FUNCTION crm.set_subscription(p_device uuid,p_version bigint,p_token text,p_platform text,p_enabled boolean)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE v bigint;BEGIN PERFORM crm.require_mobile('crm.push.write');PERFORM crm.require_mobile_device(p_device);PERFORM crm.lock_mobile_head();PERFORM 1 FROM crm.mobile_devices WHERE company_id=core.current_company()AND id=p_device FOR UPDATE;PERFORM crm.require_mobile_device(p_device);PERFORM crm.require_mobile('crm.push.write');IF length(p_token)NOT BETWEEN 20 AND 4096 OR p_token IS NULL OR p_token~'[[:space:][:cntrl:]]'OR p_platform IS NULL OR p_platform NOT IN('ANDROID','IOS','WEB')THEN RAISE EXCEPTION 'Valid push token/platform required' USING ERRCODE='HR422';END IF;SELECT version INTO v FROM crm.push_subscriptions WHERE company_id=core.current_company()AND device_id=p_device FOR UPDATE;IF coalesce(v,0)IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'Subscription version conflict' USING ERRCODE='HR409';END IF;IF EXISTS(SELECT 1 FROM crm.push_subscriptions WHERE company_id=core.current_company()AND token=p_token AND device_id<>p_device)THEN
 IF EXISTS(SELECT 1 FROM crm.push_subscriptions s JOIN crm.mobile_devices d ON d.company_id=s.company_id AND d.id=s.device_id WHERE s.company_id=core.current_company()AND s.token=p_token AND s.device_id<>p_device AND s.actor_id=core.current_actor()AND(NOT s.enabled OR NOT d.active))THEN UPDATE crm.push_subscriptions SET token='revoked:'||device_id::text,token_hash=sha256(convert_to('revoked:'||device_id::text,'UTF8')),enabled=false WHERE company_id=core.current_company()AND token=p_token AND device_id<>p_device;ELSE RAISE EXCEPTION 'Token already registered; revoke previous owned device first' USING ERRCODE='HR409';END IF;END IF;INSERT INTO crm.push_subscriptions(company_id,device_id,actor_id,token,token_hash,platform,enabled)VALUES(core.current_company(),p_device,core.current_actor(),p_token,sha256(convert_to(p_token,'UTF8')),p_platform,p_enabled)ON CONFLICT(company_id,device_id)DO UPDATE SET token=excluded.token,token_hash=excluded.token_hash,platform=excluded.platform,enabled=excluded.enabled;
 IF p_enabled THEN INSERT INTO crm.push_jobs(company_id,message_id,device_id,subscription_version)
 SELECT j.company_id,j.message_id,j.device_id,s.version FROM crm.push_jobs j JOIN crm.push_subscriptions s ON s.company_id=j.company_id AND s.device_id=j.device_id JOIN crm.notification_messages m ON m.company_id=j.company_id AND m.id=j.message_id WHERE j.company_id=core.current_company()AND j.device_id=p_device AND j.subscription_version<>s.version AND j.state IN('PENDING','RETRY')AND m.read_at IS NULL AND m.expires_at>now()AND crm.notification_source_visible(m.source_type,m.source_id,m.recipient_id)ON CONFLICT DO NOTHING;END IF;
 UPDATE crm.push_jobs j SET state='CANCELLED',last_error='subscription_changed'WHERE j.company_id=core.current_company()AND j.device_id=p_device AND j.state IN('PENDING','RETRY')AND j.subscription_version<>(SELECT version FROM crm.push_subscriptions WHERE company_id=j.company_id AND device_id=j.device_id);RETURN crm.subscription_view(p_device);END$$;
CREATE FUNCTION crm.push_eligible(p_id uuid)RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$SELECT EXISTS(SELECT 1 FROM crm.push_jobs j JOIN crm.notification_messages m ON m.company_id=j.company_id AND m.id=j.message_id JOIN crm.push_subscriptions s ON s.company_id=j.company_id AND s.device_id=j.device_id AND s.version=j.subscription_version AND s.actor_id=m.recipient_id AND s.enabled JOIN crm.mobile_devices d ON d.company_id=s.company_id AND d.id=s.device_id AND d.actor_id=s.actor_id AND d.active LEFT JOIN crm.notification_preferences p ON p.company_id=s.company_id AND p.actor_id=s.actor_id WHERE j.id=p_id AND j.company_id=core.current_company()AND m.expires_at>now()AND m.read_at IS NULL AND crm.member_permission(s.actor_id,'crm.notifications.read')AND crm.member_permission(s.actor_id,'crm.push.write')AND crm.member_permission(s.actor_id,'crm.mobile.sync')AND coalesce(p.push_enabled,true)AND CASE WHEN m.source_type='TASK'THEN coalesce(p.tasks_push,true)ELSE coalesce(p.notes_push,true)END AND crm.notification_source_visible(m.source_type,m.source_id,m.recipient_id)AND(m.source_type<>'NOTE'OR EXISTS(SELECT 1 FROM crm.note_follows nf WHERE nf.company_id=m.company_id AND nf.note_id=m.source_id AND nf.actor_id=m.recipient_id AND nf.enabled))AND(m.event<>'REMINDER'OR EXISTS(SELECT 1 FROM crm.tasks t WHERE t.company_id=m.company_id AND t.id=m.source_id AND t.state IN('OPEN','IN_PROGRESS')AND t.reminder_generation=m.generation)))$$;
CREATE FUNCTION crm.claim_push()RETURNS TABLE(job_id uuid,lease uuid)LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE j crm.push_jobs;tok uuid;BEGIN
 -- A crashed sender may already have reached FCM. Never blindly resend an expired lease.
 WITH lost AS(UPDATE crm.push_jobs SET state='UNKNOWN',last_error='sender_lease_expired',lease_token=NULL,lease_until=NULL WHERE state='PROCESSING'AND lease_until<=now()RETURNING *)INSERT INTO crm.push_attempts(job_id,company_id,attempt,state,error)SELECT id,company_id,attempts,'UNKNOWN','sender_lease_expired'FROM lost ON CONFLICT DO NOTHING;
 SELECT*INTO j FROM crm.push_jobs WHERE state IN('PENDING','RETRY')AND available_at<=now()AND attempts<5 ORDER BY available_at,created_at,id FOR UPDATE SKIP LOCKED LIMIT 1;IF NOT FOUND THEN RETURN;END IF;tok:=gen_random_uuid();UPDATE crm.push_jobs SET state='PROCESSING',attempts=attempts+1,lease_token=tok,lease_until=now()+interval '2 minutes'WHERE id=j.id;RETURN QUERY SELECT j.id,tok;END$$;
CREATE FUNCTION crm.load_push(p_id uuid,p_lease uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE j crm.push_jobs;BEGIN SELECT*INTO j FROM crm.push_jobs WHERE id=p_id AND state='PROCESSING'AND lease_token=p_lease AND lease_until>now();IF NOT FOUND THEN RAISE EXCEPTION 'Push lease unavailable' USING ERRCODE='HR409';END IF;PERFORM set_config('htt.company_id',j.company_id::text,true);IF NOT crm.push_eligible(j.id)THEN RAISE EXCEPTION 'Push source or subscription changed' USING ERRCODE='42501';END IF;RETURN(SELECT jsonb_build_object('token',s.token,'messageId',m.id,'companyId',m.company_id,'sourceType',m.source_type,'sourceId',m.source_id)FROM crm.notification_messages m JOIN crm.push_subscriptions s ON s.company_id=m.company_id AND s.device_id=j.device_id WHERE m.company_id=j.company_id AND m.id=j.message_id);END$$;
CREATE FUNCTION crm.finish_push(p_id uuid,p_lease uuid,p_state text,p_error text,p_provider text,p_retry_after int DEFAULT 0)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE j crm.push_jobs;st text:=p_state;err text:=left(p_error,100);BEGIN SELECT*INTO j FROM crm.push_jobs WHERE id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Push unavailable' USING ERRCODE='HR409';END IF;PERFORM set_config('htt.company_id',j.company_id::text,true);PERFORM crm.lock_mobile_head();SELECT*INTO j FROM crm.push_jobs WHERE id=p_id FOR UPDATE;IF j.state<>'PROCESSING'OR j.lease_token IS DISTINCT FROM p_lease OR j.lease_until<=now()THEN RAISE EXCEPTION 'Push lease stale' USING ERRCODE='HR409';END IF;IF st IS NULL OR st NOT IN('SUCCEEDED','RETRY','FAILED','CANCELLED','UNKNOWN')OR p_provider IS NOT NULL AND length(p_provider)>500 THEN RAISE EXCEPTION 'Invalid push result' USING ERRCODE='HR422';END IF;PERFORM set_config('htt.company_id',j.company_id::text,true);IF NOT crm.push_eligible(j.id)AND st IN('RETRY','FAILED')THEN st:='CANCELLED';err:='push_access_changed';END IF;IF st='RETRY'AND j.attempts>=5 THEN st:='FAILED';END IF;IF st='SUCCEEDED'AND coalesce(length(p_provider),0)=0 THEN RAISE EXCEPTION 'Provider receipt required' USING ERRCODE='HR422';END IF;
 IF err='push_token_unregistered'THEN UPDATE crm.push_subscriptions SET enabled=false WHERE company_id=j.company_id AND device_id=j.device_id AND version=j.subscription_version;END IF;
 UPDATE crm.push_jobs SET state=st,last_error=err,provider_id=p_provider,lease_token=NULL,lease_until=NULL,available_at=now()+make_interval(secs=>least(86400,greatest(coalesce(p_retry_after,0),60*power(2,j.attempts)::int)))WHERE id=p_id;INSERT INTO crm.push_attempts(job_id,company_id,attempt,state,error)VALUES(j.id,j.company_id,j.attempts,st,err);END$$;
CREATE FUNCTION crm.push_status(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN IF NOT crm.message_visible(p_id)THEN RAISE EXCEPTION 'Message unavailable' USING ERRCODE='HT404';END IF;RETURN(SELECT coalesce(jsonb_agg(jsonb_build_object('jobId',id,'deviceId',device_id,'state',state,'attempts',attempts,'lastError',last_error,'availableAt',available_at)ORDER BY created_at,id),'[]')FROM crm.push_jobs WHERE company_id=core.current_company()AND message_id=p_id);END$$;
CREATE FUNCTION crm.retry_push(p_id uuid,p_expected text,p_accept_duplicate boolean)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE j crm.push_jobs;BEGIN PERFORM crm.require_mobile('crm.push.write');SELECT*INTO j FROM crm.push_jobs WHERE company_id=core.current_company()AND id=p_id;IF NOT FOUND OR NOT crm.message_visible(j.message_id)THEN RAISE EXCEPTION 'Push unavailable' USING ERRCODE='HT404';END IF;PERFORM crm.lock_mobile_head();SELECT*INTO j FROM crm.push_jobs WHERE company_id=core.current_company()AND id=p_id FOR UPDATE;IF j.state IS DISTINCT FROM p_expected OR j.state NOT IN('FAILED','UNKNOWN')OR NOT crm.push_eligible(j.id)THEN RAISE EXCEPTION 'Push retry state/access conflict' USING ERRCODE='HR409';END IF;IF j.state='UNKNOWN'AND p_accept_duplicate IS DISTINCT FROM true THEN RAISE EXCEPTION 'Explicit duplicate-delivery acknowledgement required' USING ERRCODE='HR422';END IF;IF j.attempts>=5 THEN RAISE EXCEPTION 'Push attempt limit reached' USING ERRCODE='HR409';END IF;UPDATE crm.push_jobs SET state='RETRY',available_at=now(),last_error=NULL WHERE id=j.id;END$$;

CREATE FUNCTION crm.authorize_task_data(p_data jsonb)RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE u uuid;cust uuid;BEGIN PERFORM crm.require_mobile('crm.tasks.read');PERFORM crm.require_mobile('crm.tasks.write');PERFORM crm.validate_task(p_data);u:=(p_data->>'assigneeId')::uuid;cust:=(p_data->>'customerId')::uuid;IF NOT crm.member_customer(core.current_actor(),cust)OR NOT crm.member_customer(u,cust)OR NOT crm.member_permission(u,'crm.tasks.read')OR NOT crm.member_permission(u,'crm.tasks.write')THEN RAISE EXCEPTION 'Task or assignee access denied' USING ERRCODE='42501';END IF;END$$;
CREATE FUNCTION crm.task_push(p_device uuid,p_operation uuid,p_sequence bigint,p_request jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE c uuid:=core.current_company();dev crm.mobile_devices;old crm.mobile_operations;res jsonb;target uuid:=(p_request->>'id')::uuid;act text:=p_request->>'action';BEGIN
 PERFORM crm.require_mobile_device(p_device);PERFORM crm.require_mobile('crm.tasks.read');PERFORM crm.require_mobile('crm.tasks.write');IF act='CREATE'THEN PERFORM crm.authorize_task_data(p_request->'data');IF crm.task_visible_to(target,core.current_actor())AND EXISTS(SELECT 1 FROM crm.tasks WHERE company_id=c AND id=target AND state='DELETED')THEN RAISE EXCEPTION 'Task unavailable' USING ERRCODE='HT404';END IF;ELSE PERFORM crm.require_task(target,true);IF act<>'DELETE'THEN PERFORM crm.require_live_task(target);END IF;END IF;
 PERFORM crm.lock_mobile_head();SELECT*INTO dev FROM crm.mobile_devices WHERE company_id=c AND id=p_device FOR UPDATE;PERFORM crm.require_mobile_device(p_device);IF act='CREATE'THEN PERFORM crm.authorize_task_data(p_request->'data');IF crm.task_visible_to(target,core.current_actor())AND EXISTS(SELECT 1 FROM crm.tasks WHERE company_id=c AND id=target AND state='DELETED')THEN RAISE EXCEPTION 'Task unavailable' USING ERRCODE='HT404';END IF;ELSE PERFORM crm.require_task(target,true);IF act<>'DELETE'THEN PERFORM crm.require_live_task(target);END IF;END IF;
 SELECT*INTO old FROM crm.mobile_operations WHERE company_id=c AND operation_id=p_operation;IF FOUND THEN IF old.device_id<>p_device OR old.device_sequence<>p_sequence OR old.request<>p_request THEN RAISE EXCEPTION 'Operation identity reused' USING ERRCODE='HR409';END IF;RETURN old.response;END IF;
 IF p_operation IS NULL OR p_sequence IS NULL OR p_sequence<>dev.last_sequence+1 THEN RAISE EXCEPTION 'Device sequence gap or conflicting replay' USING ERRCODE='HR409';END IF;
 BEGIN res:=crm.task_command(target,act,(p_request->>'version')::bigint,p_request->'data');res:=jsonb_build_object('status','APPLIED','entity',res);EXCEPTION WHEN SQLSTATE'HR409'THEN res:=jsonb_build_object('status','CONFLICT','id',target,'serverVersion',(SELECT version FROM crm.tasks WHERE company_id=c AND id=target AND crm.task_visible_to(target,core.current_actor())));END;
 UPDATE crm.mobile_devices SET last_sequence=p_sequence WHERE company_id=c AND id=p_device;INSERT INTO crm.mobile_operations(company_id,operation_id,device_id,device_sequence,request,response)VALUES(c,p_operation,p_device,p_sequence,p_request,res);RETURN res;END$$;
CREATE OR REPLACE FUNCTION crm.require_mobile_device(p uuid)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile('crm.mobile.sync');IF NOT(crm.mobile_permission('crm.drafts.read')OR crm.mobile_permission('crm.tasks.read')OR crm.mobile_permission('crm.notifications.read'))THEN RAISE EXCEPTION 'Mobile read permission required' USING ERRCODE='42501';END IF;IF NOT EXISTS(SELECT 1 FROM crm.mobile_devices WHERE company_id=core.current_company()AND id=p AND actor_id=core.current_actor()AND active)THEN RAISE EXCEPTION 'Device access denied' USING ERRCODE='42501';END IF;END$$;
CREATE OR REPLACE FUNCTION crm.mobile_pull(p_device uuid,p_after bigint,p_auth text,p_limit int DEFAULT 100)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE high bigint;next_seq bigint;items jsonb;auth text;dev crm.mobile_devices;BEGIN
 PERFORM crm.require_mobile_device(p_device);IF p_after<0 OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Invalid sync page' USING ERRCODE='HR422';END IF;
 -- Commit-ordered head plus device epoch: scope changes, expiry and reset invalidate old cursors.
 PERFORM crm.lock_mobile_head();SELECT*INTO dev FROM crm.mobile_devices WHERE company_id=core.current_company()AND id=p_device FOR UPDATE;PERFORM crm.require_mobile_device(p_device);
 IF p_after=0 THEN UPDATE crm.mobile_devices SET sync_epoch=gen_random_uuid(),cursor_expires_at=now()+interval '30 days'WHERE company_id=core.current_company()AND id=p_device RETURNING*INTO dev;END IF;auth:=md5(crm.mobile_auth_hash()||dev.sync_epoch::text);
 IF p_after>0 AND(p_auth IS DISTINCT FROM auth OR dev.cursor_expires_at<=now())THEN RAISE EXCEPTION 'Cursor expired or authorization changed; discard cached CRM objects and restart at zero' USING ERRCODE='HR409';END IF;
 SELECT sequence INTO high FROM crm.mobile_heads WHERE company_id=core.current_company();IF p_after>high THEN RAISE EXCEPTION 'Cursor ahead of server; reset required' USING ERRCODE='HR409';END IF;
 SELECT coalesce(max(sequence),p_after),coalesce(jsonb_agg(payload ORDER BY sequence)FILTER(WHERE allowed),'[]')INTO next_seq,items FROM(
 SELECT sequence,payload,allowed FROM(
 SELECT d.sequence,jsonb_build_object('sequence',d.sequence,'entityType','DRAFT','tombstone',d.tombstone,'draft',d.snapshot)AS payload,crm.mobile_permission('crm.drafts.read')AND(d.owner_id=core.current_actor()OR crm.mobile_reviewer())AND crm.mobile_customer_visible(d.customer_id)AS allowed FROM crm.mobile_changes d WHERE d.company_id=core.current_company()AND d.sequence>p_after
 UNION ALL
 SELECT e.sequence,jsonb_build_object('sequence',e.sequence,'entityType',e.entity_type,'tombstone',e.tombstone,'entity',e.snapshot),crm.mobile_customer_visible(e.customer_id)AND CASE WHEN e.entity_type='BRANCH_GEO'THEN crm.mobile_permission('crm.maps.read')WHEN e.entity_type='ATTACHMENT'AND e.visibility='DRAFT'THEN crm.mobile_permission('crm.drafts.read')AND(e.owner_id=core.current_actor()OR crm.mobile_reviewer())AND EXISTS(SELECT 1 FROM crm.mobile_drafts d WHERE d.company_id=e.company_id AND d.id=e.entity_id AND d.state<>'DELETED')ELSE crm.collab_event_visible(e.entity_type,e.entity_id,e.owner_id,e.visibility,e.tombstone)END FROM crm.collaboration_changes e WHERE e.company_id=core.current_company()AND e.sequence>p_after
 UNION ALL
 SELECT t.sequence,jsonb_build_object('sequence',t.sequence,'entityType','TASK','tombstone',t.snapshot->>'state'='DELETED','entity',t.snapshot),crm.task_visible_to(t.task_id,core.current_actor())AND(t.snapshot->>'state'='DELETED'OR EXISTS(SELECT 1 FROM crm.tasks current_task WHERE current_task.company_id=t.company_id AND current_task.id=t.task_id AND current_task.state<>'DELETED'))AND((t.snapshot->>'creatorId')::uuid=core.current_actor()OR(t.snapshot->>'assigneeId')::uuid=core.current_actor()OR crm.mobile_permission('crm.tasks.manage'))FROM crm.task_changes t WHERE t.company_id=core.current_company()AND t.sequence>p_after
 UNION ALL
 SELECT n.sequence,jsonb_build_object('sequence',n.sequence,'entityType','MESSAGE','tombstone',false,'entity',CASE WHEN crm.message_visible(n.message_id)THEN crm.message_json(n.message_id)ELSE NULL END),crm.message_visible(n.message_id)FROM crm.notification_changes n WHERE n.company_id=core.current_company()AND n.sequence>p_after
 )u ORDER BY sequence LIMIT p_limit)s;RETURN jsonb_build_object('items',items,'nextSequence',next_seq,'auth',auth,'hasMore',next_seq<high,'resetRequired',false,'cursorExpiresAt',dev.cursor_expires_at);
END$$;

DO $$DECLARE p record;BEGIN FOR p IN SELECT oid::regprocedure AS fn FROM pg_proc WHERE pronamespace='crm'::regnamespace AND proname=ANY(ARRAY['member_permission','member_customer','task_visible_to','require_task','task_json','notification_source_visible','message_visible','message_json','emit_message','queue_message','emit_task','validate_task','task_command','task_list','task_history_view','message_list','mark_message','follow_note','note_notification','deliver_due_reminders','preferences_view','set_preferences','subscription_view','set_subscription','push_eligible','claim_push','load_push','finish_push','push_status','retry_push','authorize_task_data','task_push'])LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',p.fn);END LOOP;END$$;
REVOKE ALL ON FUNCTION identity.seed_task_roles(uuid)FROM PUBLIC;
GRANT EXECUTE ON FUNCTION crm.require_task(uuid,boolean),crm.task_json(uuid),crm.task_list(jsonb),crm.task_history_view(uuid),crm.task_command(uuid,text,bigint,jsonb),crm.authorize_task_data(jsonb),crm.task_push(uuid,uuid,bigint,jsonb),crm.message_visible(uuid),crm.message_json(uuid),crm.message_list(boolean,int,int),crm.mark_message(uuid,bigint,boolean),crm.follow_note(uuid,boolean,bigint),crm.preferences_view(),crm.set_preferences(bigint,boolean,boolean,boolean),crm.subscription_view(uuid),crm.set_subscription(uuid,bigint,text,text,boolean),crm.push_status(uuid),crm.retry_push(uuid,text,boolean)TO htt_app;
GRANT EXECUTE ON FUNCTION crm.deliver_due_reminders(int),crm.claim_push(),crm.load_push(uuid,uuid),crm.finish_push(uuid,uuid,text,text,text,int)TO htt_worker;
CREATE FUNCTION crm.require_push_retry(p_id uuid)RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile('crm.push.write');IF NOT EXISTS(SELECT 1 FROM crm.push_jobs WHERE company_id=core.current_company()AND id=p_id AND crm.message_visible(message_id)AND crm.push_eligible(id))THEN RAISE EXCEPTION 'Push unavailable' USING ERRCODE='HT404';END IF;END$$;
CREATE FUNCTION crm.action_centre()RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE d date;items jsonb;tasks jsonb;BEGIN PERFORM crm.require_mobile('crm.tasks.read');SELECT(now()AT TIME ZONE timezone)::date INTO d FROM core.companies WHERE id=core.current_company();
 SELECT jsonb_build_object('open',count(*)FILTER(WHERE state IN('OPEN','IN_PROGRESS')),'overdue',count(*)FILTER(WHERE state IN('OPEN','IN_PROGRESS')AND due_at<now()),'dueNext7Days',count(*)FILTER(WHERE state IN('OPEN','IN_PROGRESS')AND due_at>=now()AND due_at<now()+interval '7 days'))INTO tasks FROM crm.tasks WHERE company_id=core.current_company()AND crm.task_visible_to(id,core.current_actor());
 WITH documents AS(SELECT i.id,'AR'::text side,i.customer_id counterparty,i.due_on,l.id line FROM sales.invoices i JOIN sales.invoice_lines l ON l.company_id=i.company_id AND l.invoice_id=i.id WHERE i.company_id=core.current_company()AND crm.mobile_permission('accounting.reports.read')AND crm.mobile_customer_visible(i.customer_id)
 UNION ALL SELECT b.id,'AP',b.supplier_id,b.due_on,l.id FROM purchase.bills b JOIN purchase.bill_lines l ON l.company_id=b.company_id AND l.bill_id=b.id WHERE b.company_id=core.current_company()AND crm.mobile_permission('accounting.reports.read')),
 balances AS(SELECT m.side,m.item_line_id,sum(m.amount)amount FROM accounting.report_open_item_movements m JOIN accounting.report_control_dates dt ON dt.company_id=m.company_id AND dt.side=m.side AND dt.source_document_id=m.source_document_id WHERE m.company_id=core.current_company()AND dt.posting_date<=d AND crm.mobile_permission('accounting.reports.read')GROUP BY m.side,m.item_line_id),
 due AS(SELECT x.id,x.side,x.counterparty,x.due_on,sum(greatest(b.amount,0))amount FROM documents x JOIN balances b ON b.item_line_id=x.line AND b.side=x.side WHERE x.due_on<d+7 GROUP BY x.id,x.side,x.counterparty,x.due_on HAVING sum(greatest(b.amount,0))>0 ORDER BY x.due_on,x.id LIMIT 100)
 SELECT coalesce(jsonb_agg(jsonb_build_object('documentId',id,'side',side,'counterpartyId',counterparty,'dueOn',due_on,'outstanding',amount::text)ORDER BY due_on,id),'[]')INTO items FROM due;
 RETURN jsonb_build_object('asOf',now(),'businessDate',d,'tasks',tasks,'messages',CASE WHEN crm.mobile_permission('crm.notifications.read')THEN crm.message_list(true,20,0)ELSE NULL END,'dueFinancialItems',items,'financialItemsLimit',100,'financialItemsAuthorized',crm.mobile_permission('accounting.reports.read'));END$$;
CREATE FUNCTION crm.require_live_task(p_id uuid)RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_task(p_id);IF EXISTS(SELECT 1 FROM crm.tasks WHERE company_id=core.current_company()AND id=p_id AND state='DELETED')THEN RAISE EXCEPTION 'Task unavailable' USING ERRCODE='HT404';END IF;END$$;
CREATE FUNCTION crm.task_create_guard(p_id uuid,p_data jsonb)RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.authorize_task_data(p_data);IF EXISTS(SELECT 1 FROM crm.tasks WHERE company_id=core.current_company()AND id=p_id)THEN PERFORM crm.require_live_task(p_id);END IF;END$$;
REVOKE ALL ON FUNCTION crm.require_push_retry(uuid),crm.action_centre(),crm.require_live_task(uuid),crm.task_create_guard(uuid,jsonb)FROM PUBLIC;
GRANT EXECUTE ON FUNCTION crm.require_push_retry(uuid),crm.action_centre(),crm.require_live_task(uuid),crm.task_create_guard(uuid,jsonb)TO htt_app;

CREATE FUNCTION crm.task_offline_cache_guard(p_id uuid)RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN IF crm.task_visible_to(p_id,core.current_actor())AND EXISTS(SELECT 1 FROM crm.tasks WHERE company_id=core.current_company()AND id=p_id AND state='DELETED')THEN RAISE EXCEPTION 'Task unavailable' USING ERRCODE='HT404';END IF;END$$;
REVOKE ALL ON FUNCTION crm.task_offline_cache_guard(uuid)FROM PUBLIC;GRANT EXECUTE ON FUNCTION crm.task_offline_cache_guard(uuid)TO htt_app;
CREATE FUNCTION crm.follow_view(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile('crm.notifications.read');PERFORM crm.require_collab(p_id);IF NOT EXISTS(SELECT 1 FROM crm.collaboration_objects WHERE company_id=core.current_company()AND id=p_id AND kind='NOTE'AND state='ACTIVE')THEN RAISE EXCEPTION 'Active note required' USING ERRCODE='HT404';END IF;RETURN coalesce((SELECT jsonb_build_object('noteId',note_id,'enabled',enabled,'version',version)FROM crm.note_follows WHERE company_id=core.current_company()AND note_id=p_id AND actor_id=core.current_actor()),jsonb_build_object('noteId',p_id,'enabled',false,'version',0));END$$;
CREATE FUNCTION crm.task_assignees(p_customer uuid,p_q text,p_size int,p_offset int)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM crm.require_mobile('crm.tasks.read');PERFORM crm.require_mobile('crm.tasks.write');IF NOT crm.mobile_customer_visible(p_customer)THEN RAISE EXCEPTION 'Customer scope denied' USING ERRCODE='42501';END IF;IF p_size NOT BETWEEN 1 AND 100 OR p_offset<0 OR length(p_q)>100 THEN RAISE EXCEPTION 'Invalid directory filter' USING ERRCODE='HR422';END IF;RETURN(SELECT coalesce(jsonb_agg(jsonb_build_object('userId',id,'displayName',display_name)ORDER BY display_name,id),'[]')FROM(SELECT u.id,u.display_name FROM identity.users u WHERE u.active AND crm.member_permission(u.id,'crm.tasks.read')AND crm.member_permission(u.id,'crm.tasks.write')AND crm.member_customer(u.id,p_customer)AND(p_q IS NULL OR position(lower(p_q)IN lower(u.display_name))>0)ORDER BY u.display_name,u.id LIMIT p_size OFFSET p_offset)s);END$$;
REVOKE ALL ON FUNCTION crm.follow_view(uuid),crm.task_assignees(uuid,text,int,int)FROM PUBLIC;GRANT EXECUTE ON FUNCTION crm.follow_view(uuid),crm.task_assignees(uuid,text,int,int)TO htt_app;
